/* AUTO-GENERATED by scripts/bundle-dev-sql.mjs — อย่าแก้มือ รัน npm run build */
var DEV_SQL_BUNDLE={"01_migration_auth_rls.sql":"-- ============================================================================\n-- SAEDU Flow — Migrate to real Supabase Auth + enable RLS\n-- Run this entire file in: Supabase Dashboard → SQL Editor → New query → Run\n-- Uses your own dashboard session (DB owner) — never needs the service_role key.\n-- Safe to run now: this script creates policies but does NOT enable RLS on\n-- any table (see 02_enable_rls.sql, a separate file, for that — run it later,\n-- only once accounts are backfilled & verified per Phase D of the plan).\n-- The live app keeps working exactly as before until 02_enable_rls.sql runs.\n-- ============================================================================\n\n-- ── STEP 0: duplicate-email audit — MUST be empty before continuing ─────────\n-- If this returns any rows, fix those duplicates first (the linking trigger\n-- in step 3 matches accounts by email, so duplicates would link incorrectly).\nselect email, count(*) from public.users group by email having count(*) > 1;\n-- ^ run this separately first and confirm 0 rows before running the rest.\n\n\n-- ── STEP 1: linking column ───────────────────────────────────────────────\n-- on delete set null: lets admin-delete-user (Edge Function) remove the\n-- auth.users row in either order relative to the public.users row, without\n-- the FK blocking it.\nalter table public.users add column if not exists auth_uid uuid unique references auth.users(id) on delete set null;\n\n-- case-insensitive unique index on email, required for the trigger's\n-- \"on conflict\" matching to be reliable regardless of how email was typed.\ncreate unique index if not exists users_email_lower_idx on public.users (lower(email));\n\n-- registration no longer pre-checks \"is this student_id already used\" client\n-- side (anon can't read the users table anymore — that's the whole point of\n-- this migration). Enforce it here instead: a duplicate now fails the whole\n-- signUp() server-side (the insert trigger raises, rolling back the\n-- newly-created auth.users row too), surfaced to the client as an error.\ncreate unique index if not exists users_student_id_idx on public.users (student_id) where student_id is not null;\n\n\n-- ── STEP 2: helper — find the public.users row for the current request ────\ncreate or replace function public.current_profile()\nreturns public.users\nlanguage sql stable security definer\nas $$\n  select * from public.users where auth_uid = auth.uid() limit 1;\n$$;\n\ncreate or replace function public.is_admin()\nreturns boolean\nlanguage sql stable security definer\nas $$\n  select exists (\n    select 1 from public.users\n    where auth_uid = auth.uid() and role_code in ('ROLE-SYS','ROLE-STF')\n  );\n$$;\n\n-- Login currently accepts either student_id or email (auth.js). A brand new\n-- anonymous caller can't be given a broad SELECT on users just to resolve\n-- this, so expose only this narrow lookup as an RPC instead.\ncreate or replace function public.resolve_login_email(identifier text)\nreturns text\nlanguage sql stable security definer\nas $$\n  select coalesce(\n    (select email from public.users where student_id = identifier limit 1),\n    identifier\n  );\n$$;\n\ngrant execute on function public.resolve_login_email(text) to anon, authenticated;\n\n\n-- ── STEP 3: link new/backfilled auth.users rows to public.users by email ───\n-- Reads everything from raw_user_meta_data (passed via supabase.auth.signUp's\n-- options.data, or via the Admin API's user_metadata during backfill) so a\n-- brand-new self-registration is fully populated at insert time — no\n-- follow-up \"patch after signup\" step needed, which would otherwise depend\n-- on email-confirmation being disabled to have an active session available.\ncreate or replace function public.link_auth_user()\nreturns trigger\nlanguage plpgsql security definer\nas $$\nbegin\n  insert into public.users (\n    auth_uid, email, full_name, student_id, position_code, role_code,\n    department, contact_email, user_type, approval_status, is_active\n  )\n  values (\n    new.id,\n    lower(new.email),\n    coalesce(new.raw_user_meta_data->>'full_name', ''),\n    new.raw_user_meta_data->>'student_id',\n    new.raw_user_meta_data->>'position_code',\n    coalesce(new.raw_user_meta_data->>'role_code', 'ROLE-CRT'),\n    new.raw_user_meta_data->>'department',\n    coalesce(new.raw_user_meta_data->>'contact_email', lower(new.email)),\n    coalesce(new.raw_user_meta_data->>'user_type', 'gnk'),\n    'pending',\n    false\n  )\n  on conflict (email) do update set auth_uid = new.id\n  where lower(public.users.email) = lower(new.email);\n  return new;\nend;\n$$;\n\ndrop trigger if exists on_auth_user_created on auth.users;\ncreate trigger on_auth_user_created\n  after insert on auth.users\n  for each row execute function public.link_auth_user();\n\n\n-- ── STEP 4: RLS policies ─────────────────────────────────────────────────\n-- Tiering, by design (see plan doc for the full rationale):\n--  • users: precise — own row, or is_admin() for all rows.\n--  • admin-only config tables: precise — is_admin() gates writes.\n--  • document workflow tables (documents, document_files, workflow_steps,\n--    document_history, notifications, projects, doc_types, doc_type_fields,\n--    form_templates, calendar_events): SELECT open to any authenticated\n--    user (matches existing app behavior — these are fetched in full and\n--    filtered client-side today, there is no per-row secrecy intended\n--    between logged-in members). WRITE gated by authentication, with\n--    ownership checks (created_by/uploaded_by/performed_by = self) added\n--    where the app already enforces that distinction client-side\n--    (e.g. calendar_events delete, documents delete-own-draft).\n--    This closes the critical hole (anonymous access) without risking\n--    breaking the live multi-step approval workflow by over-encoding every\n--    role transition rule on day one. Tightening write rules further is a\n--    safe follow-up once this baseline is proven in production.\n\n-- users ----------------------------------------------------------------\ndrop policy if exists users_select on public.users;\ncreate policy users_select on public.users for select\n  using (auth_uid = auth.uid() or public.is_admin());\ndrop policy if exists users_update on public.users;\ncreate policy users_update on public.users for update\n  using (auth_uid = auth.uid() or public.is_admin());\ndrop policy if exists users_delete on public.users;\ncreate policy users_delete on public.users for delete\n  using (public.is_admin());\n-- no insert policy: new rows are only created by the security-definer\n-- trigger above (signUp / admin backfill), which bypasses RLS.\n\n-- documents --------------------------------------------------------------\ndrop policy if exists documents_select on public.documents;\ncreate policy documents_select on public.documents for select using (auth.uid() is not null);\ndrop policy if exists documents_insert on public.documents;\ncreate policy documents_insert on public.documents for insert\n  with check (created_by = (select id from public.current_profile()));\ndrop policy if exists documents_update on public.documents;\ncreate policy documents_update on public.documents for update using (auth.uid() is not null);\ndrop policy if exists documents_delete on public.documents;\ncreate policy documents_delete on public.documents for delete\n  using (created_by = (select id from public.current_profile()) or public.is_admin());\n\n-- document_files -----------------------------------------------------------\ndrop policy if exists document_files_all on public.document_files;\ncreate policy document_files_all on public.document_files for all\n  using (auth.uid() is not null) with check (auth.uid() is not null);\n\n-- workflow_steps -----------------------------------------------------------\ndrop policy if exists workflow_steps_all on public.workflow_steps;\ncreate policy workflow_steps_all on public.workflow_steps for all\n  using (auth.uid() is not null) with check (auth.uid() is not null);\n\n-- document_history (insert-only from the app; never updated/deleted) -------\ndrop policy if exists document_history_select on public.document_history;\ncreate policy document_history_select on public.document_history for select using (auth.uid() is not null);\ndrop policy if exists document_history_insert on public.document_history;\ncreate policy document_history_insert on public.document_history for insert\n  with check (auth.uid() is not null);\n-- no update/delete policy: history rows are immutable (app already enforces\n-- this client-side via _PROTECTED_TABLES in config.js — now enforced for real).\n\n-- notifications --------------------------------------------------------------\ndrop policy if exists notifications_select on public.notifications;\ncreate policy notifications_select on public.notifications for select using (auth.uid() is not null);\ndrop policy if exists notifications_insert on public.notifications;\ncreate policy notifications_insert on public.notifications for insert\n  with check (auth.uid() is not null);\n-- no update/delete: same immutable-log reasoning as document_history.\n\n-- form_templates -------------------------------------------------------------\ndrop policy if exists form_templates_select on public.form_templates;\ncreate policy form_templates_select on public.form_templates for select using (auth.uid() is not null);\ndrop policy if exists form_templates_write on public.form_templates;\ncreate policy form_templates_write on public.form_templates for all\n  using (public.is_admin()) with check (public.is_admin());\n\n-- calendar_events ------------------------------------------------------------\ndrop policy if exists calendar_events_select on public.calendar_events;\ncreate policy calendar_events_select on public.calendar_events for select using (auth.uid() is not null);\ndrop policy if exists calendar_events_insert on public.calendar_events;\ncreate policy calendar_events_insert on public.calendar_events for insert\n  with check (created_by = (select id from public.current_profile()));\ndrop policy if exists calendar_events_delete on public.calendar_events;\ncreate policy calendar_events_delete on public.calendar_events for delete\n  using (created_by = (select id from public.current_profile()) or public.is_admin());\n\n-- projects ---------------------------------------------------------------\ndrop policy if exists projects_select on public.projects;\ncreate policy projects_select on public.projects for select using (auth.uid() is not null);\ndrop policy if exists projects_write on public.projects;\ncreate policy projects_write on public.projects for all\n  using (public.is_admin()) with check (public.is_admin());\n\n-- doc_types / doc_type_fields (admin-managed, read by everyone) -----------\ndrop policy if exists doc_types_select on public.doc_types;\ncreate policy doc_types_select on public.doc_types for select using (auth.uid() is not null);\ndrop policy if exists doc_types_write on public.doc_types;\ncreate policy doc_types_write on public.doc_types for all\n  using (public.is_admin()) with check (public.is_admin());\n\ndrop policy if exists doc_type_fields_select on public.doc_type_fields;\ncreate policy doc_type_fields_select on public.doc_type_fields for select using (auth.uid() is not null);\ndrop policy if exists doc_type_fields_write on public.doc_type_fields;\ncreate policy doc_type_fields_write on public.doc_type_fields for all\n  using (public.is_admin()) with check (public.is_admin());\n\n-- workflow_templates / workflow_template_steps, email_templates, app_settings:\n-- SKIPPED here — see 07_create_admin_config_tables.sql, a separate later script\n-- that creates these four tables (the frontend already called them —\n-- sysAdmin.js, docForm.js, notif.js, config.js — but they didn't exist, so\n-- \"จัดการระบบ\" → ตั้งค่าระบบ/แบบฟอร์มอีเมล/เทมเพลต workflow were non-functional\n-- dead UI) and RLS-enables them in the same script.\n\n-- doc_number_settings (admin-only, both ways) ------------------------------\ndrop policy if exists doc_number_settings_all on public.doc_number_settings;\ncreate policy doc_number_settings_all on public.doc_number_settings for all\n  using (public.is_admin()) with check (public.is_admin());\n\n\n-- ── DONE — but RLS is NOT enabled yet ────────────────────────────────────\n-- This script only created the policies above; it did NOT run\n-- \"alter table ... enable row level security\" for any table, so nothing\n-- about the live app changes yet. Policies sit dormant until enabled.\n--\n-- Next: run the Phase D backfill (creates real Supabase Auth accounts for\n-- everyone, linked via the trigger above), verify a couple of test logins\n-- work end-to-end, THEN run 02_enable_rls.sql together with deploying the new\n-- frontend in the same window. Flipping RLS on without the new frontend\n-- deployed (or vice versa) will show an empty app to real users.\n","17_create_dev_role.sql":"-- ═══════════════════════════════════════════════════════════════════\n-- 17_create_dev_role.sql — role \"นักพัฒนา\" (ROLE-DEV) แบบแยกสิทธิ์จากแอดมิน\n--\n-- รันในหน้า SQL Editor ของ Supabase Dashboard (หรือ npx supabase db query --linked --file <path>)\n-- idempotent — รันซ้ำได้ปลอดภัย (และถ้าเคยรันเวอร์ชันเก่าที่ยัด ROLE-DEV เข้า is_admin()\n-- การรันไฟล์นี้จะถอน ROLE-DEV ออกจาก is_admin() ให้เองในข้อ 1)\n--\n-- โมเดลสิทธิ์: ROLE-DEV ≠ แอดมิน\n--   is_admin()  = ROLE-SYS, ROLE-STF (เหมือนเดิมตาม 01_migration_auth_rls.sql)\n--   is_dev()    = ROLE-DEV — ได้สิทธิ์เฉพาะที่เครื่องมือนักพัฒนาใช้จริง:\n--     ✓ อ่าน/ลบ system_logs (error log)\n--     ✓ อ่าน notifications (ดู log การแจ้งเตือน)\n--     ✓ เขียนตาราง config ทั้งหมด (app_settings, email_templates, workflow_templates(+steps),\n--       doc_types(+fields), doc_number_settings, projects, form_templates) — งาน \"แก้ระบบหลังบ้าน\"\n--     ✓ UPDATE documents / workflow_steps (เครื่องมือซ่อมเอกสาร)\n--     ✓ DELETE documents / document_files / workflow_steps (ลบเอกสารถาวร — phase 2)\n--     ✗ จัดการผู้ใช้เต็มรูปแบบ (ลบ/สร้าง) — ดู phase3 สำหรับอนุมัติ/แก้ role แบบจำกัด\n--     ✓ อ่าน/อัปเดต users แบบจำกัด (phase3) — อนุมัติ เปิด-ปิด แก้ role (ห้าม ROLE-SYS)\n--     ✗ ลบเอกสาร/ไฟล์/ประวัติ, สร้างเอกสารแทนคนอื่น\n--\n-- หมายเหตุ: การสมัครสมาชิกไม่มีทางได้ ROLE-DEV — ต้องให้แอดมินแก้ role ผ่านหน้า\n-- \"จัดการผู้ใช้\" (แก้ไขข้อมูล → สิทธิ์ → นักพัฒนา) เท่านั้น\n-- ═══════════════════════════════════════════════════════════════════\n\n-- 1) ยืนยันนิยาม is_admin() เดิม (ROLE-SYS, ROLE-STF) — ไม่รวม ROLE-DEV\n--    (สำคัญถ้าเคยรันไฟล์นี้เวอร์ชันแรกที่เพิ่ม ROLE-DEV เข้าไป — บรรทัดนี้ถอนออกให้)\ncreate or replace function public.is_admin()\nreturns boolean\nlanguage sql stable security definer\nas $$\n  select exists (\n    select 1 from public.users\n    where auth_uid = auth.uid() and role_code in ('ROLE-SYS','ROLE-STF')\n  );\n$$;\n\n-- 2) helper ใหม่: is_dev()\ncreate or replace function public.is_dev()\nreturns boolean\nlanguage sql stable security definer\nas $$\n  select exists (\n    select 1 from public.users\n    where auth_uid = auth.uid() and role_code = 'ROLE-DEV'\n  );\n$$;\n\n-- 3) ตาราง system_logs — บันทึก JS error จากเบราว์เซอร์ผู้ใช้ (logSysErr ใน config.js)\ncreate table if not exists public.system_logs (\n  id      uuid primary key default gen_random_uuid(),\n  at      timestamptz not null default now(),\n  level   text not null default 'error',   -- error | warn | info\n  source  text,                            -- จุดที่จับได้ เช่น window.onerror, unhandledrejection\n  message text,\n  detail  text,                            -- ข้อมูลประกอบ (stack, url) — text ตัดที่ ~2000 ตัวอักษรจาก client\n  user_id uuid references public.users(id) on delete set null\n);\n\ncreate index if not exists idx_system_logs_at on public.system_logs (at desc);\n\nalter table public.system_logs enable row level security;\n\ndrop policy if exists system_logs_insert on public.system_logs;\ncreate policy system_logs_insert on public.system_logs\n  for insert with check (auth.uid() is not null);\n\ndrop policy if exists system_logs_select on public.system_logs;\ncreate policy system_logs_select on public.system_logs\n  for select using (public.is_admin() or public.is_dev());\n\ndrop policy if exists system_logs_delete on public.system_logs;\ncreate policy system_logs_delete on public.system_logs\n  for delete using (public.is_admin() or public.is_dev());\n\n-- 4) สิทธิ์ ROLE-DEV เพิ่มเติม — policy คู่ขนานกับของแอดมิน (permissive policies ทำงานแบบ OR\n--    จึงเพิ่มได้โดยไม่แตะ policy เดิม)\n\n-- 4.1 ตาราง config (จาก 07_create_admin_config_tables.sql + 01_migration_auth_rls.sql)\ndrop policy if exists app_settings_write_dev on public.app_settings;\ncreate policy app_settings_write_dev on public.app_settings\n  for all using (public.is_dev()) with check (public.is_dev());\n\ndrop policy if exists email_templates_write_dev on public.email_templates;\ncreate policy email_templates_write_dev on public.email_templates\n  for all using (public.is_dev()) with check (public.is_dev());\n\ndrop policy if exists workflow_templates_write_dev on public.workflow_templates;\ncreate policy workflow_templates_write_dev on public.workflow_templates\n  for all using (public.is_dev()) with check (public.is_dev());\n\ndrop policy if exists workflow_template_steps_write_dev on public.workflow_template_steps;\ncreate policy workflow_template_steps_write_dev on public.workflow_template_steps\n  for all using (public.is_dev()) with check (public.is_dev());\n\ndrop policy if exists doc_types_write_dev on public.doc_types;\ncreate policy doc_types_write_dev on public.doc_types\n  for all using (public.is_dev()) with check (public.is_dev());\n\ndrop policy if exists doc_type_fields_write_dev on public.doc_type_fields;\ncreate policy doc_type_fields_write_dev on public.doc_type_fields\n  for all using (public.is_dev()) with check (public.is_dev());\n\ndrop policy if exists doc_number_settings_write_dev on public.doc_number_settings;\ncreate policy doc_number_settings_write_dev on public.doc_number_settings\n  for all using (public.is_dev()) with check (public.is_dev());\n\ndrop policy if exists projects_write_dev on public.projects;\ncreate policy projects_write_dev on public.projects\n  for all using (public.is_dev()) with check (public.is_dev());\n\ndrop policy if exists form_templates_write_dev on public.form_templates;\ncreate policy form_templates_write_dev on public.form_templates\n  for all using (public.is_dev()) with check (public.is_dev());\n\n-- 4.2 log การแจ้งเตือน — SELECT ปกติจำกัด recipient/is_admin (16_restrict_notifications_select.sql)\ndrop policy if exists notifications_select_dev on public.notifications;\ncreate policy notifications_select_dev on public.notifications\n  for select using (public.is_dev());\n\n-- 4.3 เครื่องมือซ่อมเอกสาร — UPDATE เท่านั้น (ห้าม insert/delete)\n--    การเขียน document_history ของ dev ใช้ policy เดิมได้ (performed_by = ตัวเอง — 06_tighten_audit_rls.sql)\ndrop policy if exists documents_update_dev on public.documents;\ncreate policy documents_update_dev on public.documents\n  for update using (public.is_dev()) with check (public.is_dev());\n\ndrop policy if exists workflow_steps_update_dev on public.workflow_steps;\ncreate policy workflow_steps_update_dev on public.workflow_steps\n  for update using (public.is_dev()) with check (public.is_dev());\n\ndrop policy if exists documents_delete_dev on public.documents;\ncreate policy documents_delete_dev on public.documents\n  for delete using (public.is_dev());\n\ndrop policy if exists document_files_delete_dev on public.document_files;\ncreate policy document_files_delete_dev on public.document_files\n  for delete using (public.is_dev());\n\ndrop policy if exists workflow_steps_delete_dev on public.workflow_steps;\ncreate policy workflow_steps_delete_dev on public.workflow_steps\n  for delete using (public.is_dev());\n\n-- 4.4 จัดการผู้ใช้แบบจำกัด (28_phase3_dev_users.sql)\ndrop policy if exists users_select_dev on public.users;\ncreate policy users_select_dev on public.users\n  for select using (public.is_dev());\n\ndrop policy if exists users_update_dev on public.users;\ncreate policy users_update_dev on public.users\n  for update\n  using (public.is_dev() and role_code <> 'ROLE-SYS')\n  with check (public.is_dev() and role_code <> 'ROLE-SYS');\n\n-- 5) ประกาศหน้า Login (popup ก่อนล็อกอิน)\n--    หน้า Login ยังไม่มี session — เปิดให้ anon อ่าน app_settings ได้ \"เฉพาะ\" key ประกาศหน้า login\n--    key ที่ใช้: login_announcement_active ('true'/'false'), login_announcement_title,\n--                login_announcement (ข้อความ), login_announcement_type ('info'|'warning'|'error')\n--    จัดการในการ์ด \"Popup ประกาศหน้า Login\" (แท็บตั้งค่าระบบ — ทั้งหน้าจัดการระบบของแอดมิน\n--    และแท็บจัดการระบบใน Dev Panel)\ndrop policy if exists app_settings_login_announce on public.app_settings;\ncreate policy app_settings_login_announce on public.app_settings\n  for select using (key like 'login_announcement%');\n","07_create_admin_config_tables.sql":"-- ============================================================================\n-- SAEDU Flow — create the admin-config tables the frontend already expects\n-- Run this entire file in: Supabase Dashboard → SQL Editor → New query → Run\n-- Uses your own dashboard session (DB owner) — never needs the service_role key.\n-- Safe to re-run (idempotent: create-if-not-exists tables, drop+create policies).\n-- ============================================================================\n--\n-- Problem this fixes:\n-- sysAdmin.js's \"ตั้งค่าระบบ\" / \"แบบฟอร์มอีเมล\" / \"เทมเพลต workflow\" cards (plus\n-- docForm.js's _applyWfTemplate, notif.js's email-template lookup, and\n-- config.js's loadAppSettings) all call dg()/dp() against app_settings,\n-- email_templates, workflow_templates and workflow_template_steps — but none\n-- of those four tables exist in this project. Every call is wrapped in\n-- try/catch so it silently no-ops; the UI renders but nothing ever persists.\n-- This script creates the tables with the exact columns those call sites\n-- read/write, then RLS-enables them in the same shot (no separate cutover\n-- step needed, unlike 02_enable_rls.sql — there's no pre-existing anon-key-only\n-- frontend reading these specific tables today).\n--\n-- Read access: any logged-in user (loadAppSettings runs for everyone after\n-- login; docForm.js reads workflow_templates for any doc creator; notif.js\n-- reads email_templates when any user's action triggers a notification).\n-- Write access: is_admin() only (ROLE-SYS / ROLE-STF), matching doc_types.\n\n-- app_settings ---------------------------------------------------------------\ncreate table if not exists public.app_settings (\n  key         text primary key,\n  value       text,\n  label       text,\n  value_type  text not null default 'text'\n                check (value_type in ('text','number','boolean','json')),\n  updated_by  uuid references public.users(id),\n  updated_at  timestamptz not null default now()\n);\nalter table public.app_settings enable row level security;\n\ndrop policy if exists app_settings_select on public.app_settings;\ncreate policy app_settings_select on public.app_settings for select\n  using (auth.uid() is not null);\ndrop policy if exists app_settings_write on public.app_settings;\ncreate policy app_settings_write on public.app_settings for all\n  using (public.is_admin()) with check (public.is_admin());\n\n-- email_templates --------------------------------------------------------------\ncreate table if not exists public.email_templates (\n  key             text primary key,\n  label           text,\n  subject_suffix  text,\n  extra_note      text,\n  updated_by      uuid references public.users(id),\n  updated_at      timestamptz not null default now()\n);\nalter table public.email_templates enable row level security;\n\ndrop policy if exists email_templates_select on public.email_templates;\ncreate policy email_templates_select on public.email_templates for select\n  using (auth.uid() is not null);\ndrop policy if exists email_templates_write on public.email_templates;\ncreate policy email_templates_write on public.email_templates for all\n  using (public.is_admin()) with check (public.is_admin());\n\n-- workflow_templates -----------------------------------------------------------\ncreate table if not exists public.workflow_templates (\n  id          uuid primary key default gen_random_uuid(),\n  doc_type    text not null\n                check (doc_type in ('incoming','outgoing','certificate','memo')),\n  name        text not null,\n  is_default  boolean not null default false,\n  created_by  uuid references public.users(id),\n  created_at  timestamptz not null default now()\n);\nalter table public.workflow_templates enable row level security;\n\ndrop policy if exists workflow_templates_select on public.workflow_templates;\ncreate policy workflow_templates_select on public.workflow_templates for select\n  using (auth.uid() is not null);\ndrop policy if exists workflow_templates_write on public.workflow_templates;\ncreate policy workflow_templates_write on public.workflow_templates for all\n  using (public.is_admin()) with check (public.is_admin());\n\n-- workflow_template_steps ------------------------------------------------------\ncreate table if not exists public.workflow_template_steps (\n  id             uuid primary key default gen_random_uuid(),\n  template_id    uuid not null references public.workflow_templates(id) on delete cascade,\n  step_number    int not null,\n  step_name      text not null,\n  role_required  text default '',\n  assigned_to    uuid references public.users(id),\n  deadline_days  int not null default 2,\n  locked         boolean not null default false\n);\nalter table public.workflow_template_steps enable row level security;\n\ndrop policy if exists workflow_template_steps_select on public.workflow_template_steps;\ncreate policy workflow_template_steps_select on public.workflow_template_steps for select\n  using (auth.uid() is not null);\ndrop policy if exists workflow_template_steps_write on public.workflow_template_steps;\ncreate policy workflow_template_steps_write on public.workflow_template_steps for all\n  using (public.is_admin()) with check (public.is_admin());\n","18_create_announcements.sql":"-- ═══════════════════════════════════════════════════════════════════\n-- 18_create_announcements.sql — บอร์ดประกาศหน้า Home (แดชบอร์ด)\n--\n-- รันในหน้า SQL Editor ของ Supabase Dashboard — idempotent รันซ้ำได้\n--\n-- ตาราง announcements: ประกาศหลายรายการ มีหัวข้อ/เนื้อหา/ระดับ/ปักหมุด/เปิด-ปิด\n-- แสดงเป็นการ์ด \"ประกาศ\" บนหน้าภาพรวมของทุกคนที่ล็อกอิน (homeViews.js)\n-- จัดการ (โพสต์/แก้/ปักหมุด/ปิด/ลบ) ได้ที่แท็บ \"ตั้งค่าระบบ\" — ทั้งแอดมิน (จัดการระบบ)\n-- และนักพัฒนา (Dev Panel → จัดการระบบ)\n--\n-- อ่าน: ทุกคนที่ล็อกอิน | เขียน/ลบ: is_admin() หรือ is_dev()\n-- (is_dev() มาจาก 17_create_dev_role.sql — ต้องรันไฟล์นั้นก่อนไฟล์นี้)\n-- created_by อ้าง users แบบ on delete set null — ลบผู้ใช้ไม่ต้อง unlink ประกาศก่อน\n-- ═══════════════════════════════════════════════════════════════════\n\ncreate table if not exists public.announcements (\n  id         uuid primary key default gen_random_uuid(),\n  title      text not null,\n  body       text,\n  level      text not null default 'info',   -- info | warning | error\n  pinned     boolean not null default false, -- ปักหมุดขึ้นบนสุด\n  is_active  boolean not null default true,  -- ปิด = ซ่อนจากหน้า Home แต่ยังอยู่ในหน้าจัดการ\n  created_by uuid references public.users(id) on delete set null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz\n);\n\ncreate index if not exists idx_announcements_home\n  on public.announcements (is_active, pinned desc, created_at desc);\n\nalter table public.announcements enable row level security;\n\ndrop policy if exists announcements_select on public.announcements;\ncreate policy announcements_select on public.announcements\n  for select using (auth.uid() is not null);\n\ndrop policy if exists announcements_write on public.announcements;\ncreate policy announcements_write on public.announcements\n  for all using (public.is_admin() or public.is_dev())\n  with check (public.is_admin() or public.is_dev());\n","19_user_signatures.sql":"-- ============================================================================\n-- SAEDU Flow — ลายเซ็นส่วนตัว (1 รายการต่อผู้ใช้)\n-- Run in Supabase Dashboard → SQL Editor (หลัง 01_migration_auth_rls.sql)\n-- Safe to re-run.\n-- ============================================================================\n--\n-- เก็บ path อ้างอิงใน users + ไฟล์ PNG ใน bucket ส่วนตัว user-signatures\n-- ไม่ใส่ใน user_directory view — คนอื่นอ่านลายเซ็นไม่ได้\n\nalter table public.users add column if not exists signature_path text;\nalter table public.users add column if not exists signature_updated_at timestamptz;\n\ninsert into storage.buckets (id, name, public)\nvalues ('user-signatures', 'user-signatures', false)\non conflict (id) do update set public = false;\n\ndrop policy if exists user_signatures_select on storage.objects;\ndrop policy if exists user_signatures_insert on storage.objects;\ndrop policy if exists user_signatures_update on storage.objects;\ndrop policy if exists user_signatures_delete on storage.objects;\n\ncreate policy user_signatures_select on storage.objects\n  for select to authenticated\n  using (\n    bucket_id = 'user-signatures'\n    and (storage.foldername(name))[1] = (select id::text from public.current_profile())\n  );\n\ncreate policy user_signatures_insert on storage.objects\n  for insert to authenticated\n  with check (\n    bucket_id = 'user-signatures'\n    and (storage.foldername(name))[1] = (select id::text from public.current_profile())\n  );\n\ncreate policy user_signatures_update on storage.objects\n  for update to authenticated\n  using (\n    bucket_id = 'user-signatures'\n    and (storage.foldername(name))[1] = (select id::text from public.current_profile())\n  )\n  with check (\n    bucket_id = 'user-signatures'\n    and (storage.foldername(name))[1] = (select id::text from public.current_profile())\n  );\n\ncreate policy user_signatures_delete on storage.objects\n  for delete to authenticated\n  using (\n    bucket_id = 'user-signatures'\n    and (storage.foldername(name))[1] = (select id::text from public.current_profile())\n  );\n","20_line_notifications.sql":"-- ═══════════════════════════════════════════════════════════════════\n-- LINE OA NOTIFICATIONS — คอลัมน์ผูกบัญชี LINE กับ public.users\n-- ═══════════════════════════════════════════════════════════════════\n--\n-- รันใน Supabase Dashboard SQL Editor (idempotent — รันซ้ำได้)\n-- ใช้คู่กับ Edge Functions: send-line (push แจ้งเตือน) และ\n-- line-webhook (รับ event จาก LINE เพื่อผูกบัญชีด้วยรหัส 6 หลัก)\n--\n-- โมเดลการผูกบัญชี:\n--   1. ผู้ใช้กด \"เชื่อมต่อ LINE\" ในแอป → แอปสุ่มรหัส 6 หลักเขียนลง\n--      line_link_code (+ หมดอายุ 10 นาที) ในแถวของตัวเอง\n--      (RLS เดิม users_update: auth_uid = auth.uid() ครอบอยู่แล้ว)\n--   2. ผู้ใช้แอด LINE OA เป็นเพื่อน แล้วพิมพ์รหัสส่งในแชท\n--   3. line-webhook (service role — ข้าม RLS) จับคู่รหัส → เขียน\n--      line_user_id ลงแถวนั้น แล้วล้างรหัสทิ้ง\n--\n-- ความปลอดภัย: line_user_id ไม่ถูกเพิ่มเข้า view user_directory\n-- (ผู้ใช้อื่นมองไม่เห็น) — ฝั่ง client เห็นได้เฉพาะของตัวเองผ่านแถว\n-- users ของตนเอง; การ resolve line_user_id ของ \"ผู้รับ\" ตอนส่งแจ้งเตือน\n-- ทำฝั่ง server ใน Edge Function send-line เท่านั้น\n\nalter table public.users add column if not exists line_user_id text;\nalter table public.users add column if not exists line_link_code text;\nalter table public.users add column if not exists line_link_code_expires_at timestamptz;\n\n-- LINE userId หนึ่งบัญชีผูกได้กับผู้ใช้เดียว (webhook จะย้ายการผูกให้เอง\n-- ถ้ามีการผูกซ้ำ — ล้างแถวเก่าก่อน insert ใหม่)\ncreate unique index if not exists users_line_user_id_unique\n  on public.users (line_user_id) where line_user_id is not null;\n\n-- ให้ webhook ค้นรหัสเร็ว (แถวที่มีรหัสค้างอยู่มีจำนวนน้อยมาก)\ncreate index if not exists users_line_link_code_idx\n  on public.users (line_link_code) where line_link_code is not null;\n","21_overdue_once_auto_approve.sql":"-- ════════════════════════════════════════════════════════════════════════\n-- 21_overdue_once_auto_approve.sql\n-- นโยบายใหม่สำหรับเอกสารเลยกำหนด (แทนการเตือนซ้ำรายวัน):\n--   1. อีเมลเตือนเลยกำหนด ส่งครั้งเดียวต่อเอกสาร (เดิม: วันละครั้ง)\n--   2. หลังเตือนแล้ว ถ้ายังไม่มีการดำเนินการภายใน sla_cascade_days วันทำการ\n--      (ค่าเริ่มต้น 3 — แก้ได้ใน \"ตั้งค่าระบบ\") ระบบจัดการให้อัตโนมัติ เฉพาะ 2 กรณี:\n--        a) เอกสาร pending ที่ค้างอยู่ \"ขั้นตอนสุดท้าย\" ของ workflow\n--           → อนุมัติขั้นตอนนั้นให้ (ไม่มีลายเซ็นฝังใน PDF — บันทึกใน history ชัดเจน)\n--           → เอกสารไป numbering (ขาเข้า) / completed (ประเภทอื่น) ตาม flow ปกติ\n--        b) เอกสาร completed ที่ส่งต่อแล้ว แต่ผู้รับปลายทางยังไม่กด \"รับเอกสาร\"\n--           → บันทึก 'เจ้าหน้าที่รับเอกสาร' ให้ (ข้อความเดียวกับการกดรับจริง\n--             เพราะ docDetail.js/layout.js filter ด้วย string นี้)\n--      เอกสารที่ปิด notify_overdue จะไม่ถูกเตือนและไม่ถูกจัดการอัตโนมัติ\n--\n-- ทำเป็น RPC (security definer) เพราะ:\n--   - ผู้ที่ล็อกอินตอนระบบตรวจ (sendOverdueNotifs หลัง login) มักไม่ใช่\n--     ผู้มีสิทธิ์เขียนเอกสารนั้นตาม RLS — client เขียนตรงไม่ได้\n--   - การเปลี่ยนสถานะแตะ 3 ตาราง ต้อง atomic (ฟังก์ชัน = 1 transaction)\n--   - เงื่อนไขเวลา/ขั้นตอนถูกตรวจฝั่งเซิร์ฟเวอร์ ผู้ใช้เร่งเวลาเองไม่ได้\n--\n-- ⚠️ deploy คู่กับ frontend (notif.js) ที่เรียก overdue_notif_sent_at /\n--    auto_approve_overdue — รัน SQL ก่อนหรือหลัง deploy ก็ได้ (โค้ดมี fallback)\n-- รันใน Supabase Dashboard SQL Editor\n-- ════════════════════════════════════════════════════════════════════════\n\n-- ── 1. เตือนครั้งเดียว: dedup แบบตลอดอายุเอกสาร ──────────────────────────\n-- แทนที่ของเดิม (หน้าต่าง 24 ชม.) — client เก่าที่ยังเรียกฟังก์ชันนี้\n-- จะได้พฤติกรรม \"ครั้งเดียว\" ทันทีโดยไม่ต้องรอ deploy frontend\nCREATE OR REPLACE FUNCTION public.overdue_notif_exists(p_doc uuid)\nRETURNS boolean\nLANGUAGE sql\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS(\n    SELECT 1 FROM public.notifications\n    WHERE document_id = p_doc\n      AND notification_type = 'overdue'\n  );\n$$;\nGRANT EXECUTE ON FUNCTION public.overdue_notif_exists(uuid) TO authenticated, anon;\n\n-- คืนเวลาส่งเตือนครั้งแรก (null = ยังไม่เคยเตือน) — notif.js ใช้ตัวนี้เป็นหลัก\n-- ทั้ง dedup และคำนวณ grace period ก่อนอนุมัติอัตโนมัติ\nCREATE OR REPLACE FUNCTION public.overdue_notif_sent_at(p_doc uuid)\nRETURNS timestamptz\nLANGUAGE sql\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT min(sent_at) FROM public.notifications\n  WHERE document_id = p_doc AND notification_type = 'overdue';\n$$;\nGRANT EXECUTE ON FUNCTION public.overdue_notif_sent_at(uuid) TO authenticated, anon;\n\n-- ── 2. helper: บวกวันทำการ (จ.-ศ.) — ตรรกะเดียวกับ addWorkingDays ใน utils.js ──\nCREATE OR REPLACE FUNCTION public.add_working_days(p_from timestamptz, p_days int)\nRETURNS timestamptz\nLANGUAGE plpgsql\nIMMUTABLE\nAS $$\nDECLARE\n  d timestamptz := p_from;\n  i int := 0;\nBEGIN\n  WHILE i < p_days LOOP\n    d := d + interval '1 day';\n    IF extract(isodow FROM d) < 6 THEN i := i + 1; END IF;\n  END LOOP;\n  RETURN d;\nEND;\n$$;\n\n-- ── 3. อนุมัติ/รับเอกสารอัตโนมัติเมื่อเลยกำหนดเกิน grace period ────────────\n-- คืนค่า: 'approved_numbering' | 'approved_completed' | 'accepted_forward'\n--        หรือรหัสเหตุผลที่ไม่ทำ ('in_grace', 'not_last_step', ...)\nCREATE OR REPLACE FUNCTION public.auto_approve_overdue(p_doc uuid)\nRETURNS text\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  doc record;\n  act record;\n  warn_at timestamptz;\n  grace int;\nBEGIN\n  IF auth.uid() IS NULL THEN RETURN 'not_authenticated'; END IF;\n\n  SELECT * INTO doc FROM public.documents WHERE id = p_doc FOR UPDATE;\n  IF NOT FOUND THEN RETURN 'not_found'; END IF;\n  IF coalesce(doc.notify_overdue, true) = false THEN RETURN 'notify_off'; END IF;\n  IF doc.due_date IS NULL OR doc.due_date >= current_date THEN RETURN 'not_overdue'; END IF;\n\n  -- ต้องเตือนก่อนเสมอ แล้วรอครบ grace period (วันทำการ) นับจากเวลาที่เตือนจริง\n  SELECT min(sent_at) INTO warn_at FROM public.notifications\n    WHERE document_id = p_doc AND notification_type = 'overdue';\n  IF warn_at IS NULL THEN RETURN 'no_warning_yet'; END IF;\n\n  SELECT coalesce(nullif(value,'')::int, 3) INTO grace\n    FROM public.app_settings WHERE key = 'sla_cascade_days';\n  IF grace IS NULL THEN grace := 3; END IF;\n  IF now() < public.add_working_days(warn_at, grace) THEN RETURN 'in_grace'; END IF;\n\n  -- กรณี a) ค้างขั้นตอนสุดท้ายของ workflow\n  IF doc.status = 'pending' THEN\n    SELECT * INTO act FROM public.workflow_steps\n      WHERE document_id = p_doc AND status = 'active'\n      ORDER BY step_number DESC LIMIT 1;\n    IF NOT FOUND THEN RETURN 'no_active_step'; END IF;\n    IF EXISTS (SELECT 1 FROM public.workflow_steps\n               WHERE document_id = p_doc AND step_number > act.step_number\n                 AND status <> 'done') THEN\n      RETURN 'not_last_step';\n    END IF;\n\n    UPDATE public.workflow_steps SET\n      status = 'done', action_taken = 'approve',\n      note = 'อนุมัติอัตโนมัติโดยระบบ — เลยกำหนดและไม่มีการดำเนินการหลังแจ้งเตือนภายใน '||grace||' วันทำการ',\n      action_at = now(), completed_at = now()\n      WHERE id = act.id;\n\n    UPDATE public.documents SET\n      status = CASE WHEN doc.doc_type = 'incoming' THEN 'numbering' ELSE 'completed' END,\n      current_step = least(coalesce(doc.current_step,1)+1, coalesce(doc.total_steps,1)),\n      updated_at = now()\n      WHERE id = p_doc;\n\n    INSERT INTO public.document_history(document_id, action, performed_by, note)\n      VALUES (p_doc, 'อนุมัติอัตโนมัติ (เลยกำหนด)',\n              coalesce(act.assigned_to, doc.created_by),\n              'ระบบอนุมัติขั้นตอนสุดท้าย \"'||coalesce(act.step_name,'')||'\" ให้อัตโนมัติ เนื่องจากเลยกำหนดและไม่มีการดำเนินการหลังแจ้งเตือนภายใน '||grace||' วันทำการ (ไม่มีลายเซ็นฝังในไฟล์)');\n\n    RETURN CASE WHEN doc.doc_type = 'incoming' THEN 'approved_numbering' ELSE 'approved_completed' END;\n  END IF;\n\n  -- กรณี b) รอผู้รับปลายทางกดรับเอกสาร (ส่งต่อแล้วเงียบ)\n  IF doc.status = 'completed' AND doc.forwarded_to_id IS NOT NULL THEN\n    -- เช็คการรับด้วย LIKE ให้ตรงกับ client (indexOf('เจ้าหน้าที่รับเอกสาร'))\n    IF EXISTS (SELECT 1 FROM public.document_history\n               WHERE document_id = p_doc\n                 AND action LIKE '%เจ้าหน้าที่รับเอกสาร%') THEN\n      RETURN 'already_accepted';\n    END IF;\n\n    -- action ต้องเป็น 'เจ้าหน้าที่รับเอกสาร' เป๊ะ ๆ — layout.js filter ด้วย eq.\n    INSERT INTO public.document_history(document_id, action, performed_by, note)\n      VALUES (p_doc, 'เจ้าหน้าที่รับเอกสาร', doc.forwarded_to_id,\n              'รับเอกสารอัตโนมัติโดยระบบ เนื่องจากเลยกำหนดและไม่มีการดำเนินการหลังแจ้งเตือนภายใน '||grace||' วันทำการ');\n\n    -- ล้าง forwarded state — ให้สอดคล้องกับ forward_accept() และไม่ให้ overdue scan เจอซ้ำ\n    UPDATE public.documents SET\n      forwarded_to_id = NULL,\n      forwarded_at = NULL,\n      updated_at = now()\n    WHERE id = p_doc;\n\n    RETURN 'accepted_forward';\n  END IF;\n\n  RETURN 'not_eligible';\nEND;\n$$;\nGRANT EXECUTE ON FUNCTION public.auto_approve_overdue(uuid) TO authenticated;\n\n-- ── ตรวจสอบหลังรัน ──\nSELECT proname, prosecdef AS security_definer\nFROM pg_proc\nWHERE pronamespace = 'public'::regnamespace\n  AND proname IN ('overdue_notif_exists','overdue_notif_sent_at','add_working_days','auto_approve_overdue');\n","22_scale_hardening.sql":"-- ============================================================================\n-- SAEDU Flow — scale & security hardening (รันหลัง migration_auth_rls +\n-- create_dev_role + overdue_once_auto_approve + tighten_workflow_rls +\n-- tighten_audit_rls + restrict_notifications_select)\n-- ============================================================================\n-- สิ่งที่ migration นี้ทำ:\n--   1. workflow_action()     — อนุมัติ/ตีกลับแบบ atomic (1 transaction)\n--   2. forward_accept()      — รับเอกสารส่งต่อ + ล้าง forwarded_to_id\n--   3. log_notification()    — บันทึก notifications พร้อมตรวจสิทธิ์ผู้ส่ง\n--   4. จำกัด notifications INSERT ตรง (ต้องผ่าน RPC หรือ admin/dev)\n--   5. index สำหรับ overdue scan\n--   6. app_settings.schema_version = '3' (frontend แจ้งเตือนถ้ายังไม่ deploy)\n--      รัน 23_workflow_ops_rpc.sql + 29_cron_overdue.sql ด้วยถ้ายังไม่ได้รัน\n-- รันใน Supabase Dashboard → SQL Editor (idempotent — รันซ้ำได้)\n\n-- ── helpers (reuse add_working_days จาก 21_overdue_once_auto_approve.sql) ─────\nCREATE OR REPLACE FUNCTION public.add_working_days(p_from timestamptz, p_days int)\nRETURNS timestamptz\nLANGUAGE plpgsql\nIMMUTABLE\nAS $$\nDECLARE\n  d timestamptz := p_from;\n  i int := 0;\nBEGIN\n  WHILE i < p_days LOOP\n    d := d + interval '1 day';\n    IF extract(isodow FROM d) < 6 THEN i := i + 1; END IF;\n  END LOOP;\n  RETURN d;\nEND;\n$$;\n\nCREATE OR REPLACE FUNCTION public.step_deadline_ts(p_days int)\nRETURNS timestamptz\nLANGUAGE plpgsql\nSTABLE\nAS $$\nDECLARE d timestamptz;\nBEGIN\n  d := public.add_working_days(now(), coalesce(p_days, 2));\n  RETURN date_trunc('day', d AT TIME ZONE 'Asia/Bangkok') AT TIME ZONE 'Asia/Bangkok' + interval '23 hours 59 minutes';\nEND;\n$$;\n\n-- ผู้ใช้มีสิทธิ์เขียน log แจ้งเตือนของเอกสารนี้หรือไม่\nCREATE OR REPLACE FUNCTION public.can_log_notification(p_doc uuid, p_sender uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT\n    public.is_admin()\n    OR public.is_dev()\n    OR exists (\n      select 1 from public.users u\n      where u.id = p_sender and u.role_code in ('ROLE-SYS', 'ROLE-STF')\n    )\n    OR exists (\n      select 1 from public.documents d\n      where d.id = p_doc\n        and (\n          d.created_by = p_sender\n          or d.forwarded_to_id = p_sender\n          or exists (\n            select 1 from public.workflow_steps ws\n            where ws.document_id = p_doc\n              and (ws.assigned_to = p_sender or ws.rejected_by = p_sender)\n          )\n        )\n    );\n$$;\n\n-- ── 1. Atomic approve / reject ─────────────────────────────────────────────\nCREATE OR REPLACE FUNCTION public.workflow_action(\n  p_doc uuid,\n  p_action text,\n  p_note text DEFAULT '',\n  p_revision_section text DEFAULT NULL\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_uid uuid;\n  v_doc public.documents%ROWTYPE;\n  v_cur public.workflow_steps%ROWTYPE;\n  v_nx public.workflow_steps%ROWTYPE;\n  v_all_done boolean;\n  v_nst text;\n  v_ns int;\n  v_hist text;\nBEGIN\n  SELECT id INTO v_uid FROM public.current_profile();\n  IF v_uid IS NULL THEN\n    RAISE EXCEPTION 'not authenticated';\n  END IF;\n\n  IF p_action NOT IN ('approve', 'reject') THEN\n    RAISE EXCEPTION 'invalid action';\n  END IF;\n\n  SELECT * INTO v_doc FROM public.documents WHERE id = p_doc FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'document not found'; END IF;\n\n  IF v_doc.status NOT IN ('pending', 'active', 'rejected') THEN\n    RAISE EXCEPTION 'document not in workflow state';\n  END IF;\n\n  SELECT * INTO v_cur\n  FROM public.workflow_steps\n  WHERE document_id = p_doc AND status = 'active'\n  ORDER BY step_number\n  LIMIT 1\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    SELECT * INTO v_cur\n    FROM public.workflow_steps\n    WHERE document_id = p_doc\n    ORDER BY step_number\n    LIMIT 1\n    FOR UPDATE;\n  END IF;\n\n  IF NOT FOUND THEN RAISE EXCEPTION 'no workflow steps'; END IF;\n\n  IF v_cur.assigned_to IS DISTINCT FROM v_uid\n     AND NOT public.is_admin()\n     AND NOT public.is_dev() THEN\n    RAISE EXCEPTION 'not assigned to active step';\n  END IF;\n\n  IF p_action = 'approve' THEN\n    UPDATE public.workflow_steps SET\n      status = 'done',\n      action_taken = 'approve',\n      note = coalesce(p_note, ''),\n      revision_section = p_revision_section,\n      action_at = now(),\n      completed_at = now(),\n      rejected_by = NULL\n    WHERE id = v_cur.id;\n\n    SELECT * INTO v_nx\n    FROM public.workflow_steps\n    WHERE document_id = p_doc\n      AND step_number > v_cur.step_number\n      AND status <> 'done'\n    ORDER BY step_number\n    LIMIT 1;\n\n    IF FOUND THEN\n      UPDATE public.workflow_steps SET\n        status = 'active',\n        deadline_datetime = public.step_deadline_ts(deadline_days),\n        action_taken = NULL,\n        note = NULL,\n        revision_section = NULL,\n        action_at = NULL,\n        completed_at = NULL,\n        rejected_by = NULL\n      WHERE id = v_nx.id;\n    END IF;\n\n    SELECT NOT EXISTS (\n      SELECT 1 FROM public.workflow_steps ws\n      WHERE ws.document_id = p_doc\n        AND ws.step_number > v_cur.step_number\n        AND ws.status <> 'done'\n    ) INTO v_all_done;\n\n    IF v_all_done THEN\n      v_nst := CASE WHEN v_doc.doc_type = 'incoming' THEN 'numbering' ELSE 'completed' END;\n    ELSE\n      v_nst := 'pending';\n    END IF;\n    v_hist := 'อนุมัติ / ลงนาม';\n\n  ELSE\n    UPDATE public.workflow_steps SET\n      status = 'rejected',\n      action_taken = 'reject',\n      note = coalesce(p_note, ''),\n      revision_section = p_revision_section,\n      action_at = now(),\n      completed_at = NULL,\n      rejected_by = v_uid\n    WHERE id = v_cur.id;\n\n    v_all_done := false;\n    v_nst := 'rejected';\n    v_hist := 'ส่งคืนแก้ไขไปยังผู้จัดทำ';\n  END IF;\n\n  v_ns := least(coalesce(v_doc.current_step, 1) + 1, coalesce(v_doc.total_steps, 1));\n\n  UPDATE public.documents SET\n    status = v_nst,\n    current_step = v_ns,\n    updated_at = now()\n  WHERE id = p_doc;\n\n  INSERT INTO public.document_history (document_id, action, performed_by, note)\n  VALUES (p_doc, v_hist, v_uid, coalesce(p_note, ''));\n\n  RETURN jsonb_build_object(\n    'status', v_nst,\n    'all_done', v_all_done,\n    'current_step', v_ns,\n    'cur_step_number', v_cur.step_number,\n    'cur_step_id', v_cur.id\n  );\nEND;\n$$;\n\nGRANT EXECUTE ON FUNCTION public.workflow_action(uuid, text, text, text) TO authenticated;\n\n-- ── 2. Forward accept (ล้าง forwarded_to_id — แก้ overdue scan ซ้ำซ้อน) ───\nCREATE OR REPLACE FUNCTION public.forward_accept(p_doc uuid, p_note text DEFAULT NULL)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_uid uuid;\n  v_doc public.documents%ROWTYPE;\nBEGIN\n  SELECT id INTO v_uid FROM public.current_profile();\n  IF v_uid IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;\n\n  SELECT * INTO v_doc FROM public.documents WHERE id = p_doc FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'document not found'; END IF;\n\n  IF v_doc.forwarded_to_id IS DISTINCT FROM v_uid\n     AND NOT public.is_admin()\n     AND NOT public.is_dev() THEN\n    RAISE EXCEPTION 'not forwarded to you';\n  END IF;\n\n  UPDATE public.documents SET\n    forwarded_to_id = NULL,\n    forwarded_at = NULL,\n    updated_at = now()\n  WHERE id = p_doc;\n\n  INSERT INTO public.document_history (document_id, action, performed_by, note)\n  VALUES (\n    p_doc,\n    'เจ้าหน้าที่รับเอกสาร',\n    v_uid,\n    coalesce(p_note, 'รับและอนุมัติเอกสารเรียบร้อยแล้ว')\n  );\nEND;\n$$;\n\nGRANT EXECUTE ON FUNCTION public.forward_accept(uuid, text) TO authenticated;\n\n-- ── 3. Validated notification log ───────────────────────────────────────────\nCREATE OR REPLACE FUNCTION public.log_notification(\n  p_document_id uuid,\n  p_recipient_id uuid,\n  p_recipient_email text,\n  p_subject text,\n  p_body text,\n  p_notification_type text,\n  p_status text,\n  p_sent_at timestamptz DEFAULT now()\n)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_uid uuid;\n  v_id uuid;\nBEGIN\n  SELECT id INTO v_uid FROM public.current_profile();\n  IF v_uid IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;\n\n  IF p_document_id IS NOT NULL\n     AND NOT public.can_log_notification(p_document_id, v_uid) THEN\n    RAISE EXCEPTION 'not allowed to log notification for this document';\n  END IF;\n\n  INSERT INTO public.notifications (\n    document_id, recipient_id, recipient_email,\n    subject, body, notification_type, status, sent_at\n  ) VALUES (\n    p_document_id, p_recipient_id, p_recipient_email,\n    p_subject, p_body, p_notification_type, p_status, coalesce(p_sent_at, now())\n  )\n  RETURNING id INTO v_id;\n\n  RETURN v_id;\nEND;\n$$;\n\nGRANT EXECUTE ON FUNCTION public.log_notification(uuid, uuid, text, text, text, text, text, timestamptz) TO authenticated;\n\n-- ── 4. Tighten direct notifications INSERT ──────────────────────────────────\nDROP POLICY IF EXISTS notifications_insert ON public.notifications;\nCREATE POLICY notifications_insert ON public.notifications FOR INSERT\n  WITH CHECK (public.is_admin() OR public.is_dev());\n\n-- ── 5. Index สำหรับ overdue scan (ลด full-table scan เมื่อมีผู้ใช้เยอะ) ───\nCREATE INDEX IF NOT EXISTS documents_overdue_scan_idx\n  ON public.documents (due_date)\n  WHERE notify_overdue = true AND status IN ('pending', 'completed');\n\nCREATE INDEX IF NOT EXISTS workflow_steps_active_assignee_idx\n  ON public.workflow_steps (assigned_to)\n  WHERE status = 'active';\n\n-- ── 6. Schema version marker ────────────────────────────────────────────────\nINSERT INTO public.app_settings (key, value, label, value_type)\nVALUES ('schema_version', '3', 'เวอร์ชัน schema ที่ frontend ต้องการ', 'text')\nON CONFLICT (key) DO UPDATE\n  SET value = EXCLUDED.value,\n      label = EXCLUDED.label,\n      updated_at = now();\n","23_workflow_ops_rpc.sql":"-- ============================================================================\n-- SAEDU Flow — atomic forward decline + recall (รันหลัง 22_scale_hardening.sql)\n-- ============================================================================\n--   1. forward_decline()  — ไม่อนุมัติเอกสารที่ส่งต่อ (atomic)\n--   2. recall_document()  — ผู้จัดทำดึงกลับเป็นฉบับร่าง (atomic)\n--   3. app_settings.schema_version = '3' (ถ้ายังไม่ถึง v3 จาก 29_cron_overdue.sql)\n-- รันใน Supabase Dashboard → SQL Editor (idempotent)\n\n-- ── 1. Forward decline (ส่งคืนผู้จัดทำ) ─────────────────────────────────────\nCREATE OR REPLACE FUNCTION public.forward_decline(p_doc uuid, p_note text DEFAULT '')\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_uid uuid;\n  v_doc public.documents%ROWTYPE;\n  v_first_rev uuid;\n  v_step public.workflow_steps%ROWTYPE;\nBEGIN\n  SELECT id INTO v_uid FROM public.current_profile();\n  IF v_uid IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;\n\n  IF coalesce(trim(p_note), '') = '' THEN\n    RAISE EXCEPTION 'note required';\n  END IF;\n\n  SELECT * INTO v_doc FROM public.documents WHERE id = p_doc FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'document not found'; END IF;\n\n  IF v_doc.status <> 'completed' THEN\n    RAISE EXCEPTION 'document not completed';\n  END IF;\n\n  IF v_doc.forwarded_to_id IS NULL THEN\n    RAISE EXCEPTION 'document not forwarded';\n  END IF;\n\n  IF v_doc.forwarded_to_id IS DISTINCT FROM v_uid\n     AND NOT public.is_admin()\n     AND NOT public.is_dev() THEN\n    RAISE EXCEPTION 'not forwarded to you';\n  END IF;\n\n  IF EXISTS (\n    SELECT 1 FROM public.document_history h\n    WHERE h.document_id = p_doc\n      AND h.action = 'เจ้าหน้าที่รับเอกสาร'\n  ) THEN\n    RAISE EXCEPTION 'already accepted';\n  END IF;\n\n  SELECT ws.id INTO v_first_rev\n  FROM public.workflow_steps ws\n  WHERE ws.document_id = p_doc AND ws.step_number > 1\n  ORDER BY ws.step_number\n  LIMIT 1;\n\n  IF v_first_rev IS NULL THEN\n    SELECT ws.id INTO v_first_rev\n    FROM public.workflow_steps ws\n    WHERE ws.document_id = p_doc\n    ORDER BY ws.step_number\n    LIMIT 1;\n  END IF;\n\n  FOR v_step IN\n    SELECT * FROM public.workflow_steps\n    WHERE document_id = p_doc\n    ORDER BY step_number\n    FOR UPDATE\n  LOOP\n    IF v_step.id = v_first_rev THEN\n      UPDATE public.workflow_steps SET\n        status = 'rejected',\n        action_taken = NULL,\n        note = NULL,\n        revision_section = NULL,\n        action_at = NULL,\n        completed_at = NULL,\n        rejected_by = v_uid,\n        deadline_datetime = NULL\n      WHERE id = v_step.id;\n    ELSE\n      UPDATE public.workflow_steps SET\n        status = 'pending',\n        action_taken = NULL,\n        note = NULL,\n        revision_section = NULL,\n        action_at = NULL,\n        completed_at = NULL,\n        rejected_by = NULL,\n        deadline_datetime = NULL\n      WHERE id = v_step.id;\n    END IF;\n  END LOOP;\n\n  UPDATE public.documents SET\n    status = 'rejected',\n    forwarded_to_id = NULL,\n    forwarded_at = NULL,\n    updated_at = now()\n  WHERE id = p_doc;\n\n  INSERT INTO public.document_history (document_id, action, performed_by, note)\n  VALUES (p_doc, 'ไม่อนุมัติ — ส่งคืนให้ดำเนินการใหม่', v_uid, p_note);\nEND;\n$$;\n\nGRANT EXECUTE ON FUNCTION public.forward_decline(uuid, text) TO authenticated;\n\n-- ── 2. Recall document (ดึงกลับเป็นฉบับร่าง) ─────────────────────────────\nCREATE OR REPLACE FUNCTION public.recall_document(p_doc uuid)\nRETURNS jsonb\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  v_uid uuid;\n  v_doc public.documents%ROWTYPE;\n  v_step public.workflow_steps%ROWTYPE;\n  v_notify uuid[] := '{}';\nBEGIN\n  SELECT id INTO v_uid FROM public.current_profile();\n  IF v_uid IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;\n\n  SELECT * INTO v_doc FROM public.documents WHERE id = p_doc FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'document not found'; END IF;\n\n  IF v_doc.status <> 'pending' THEN\n    RAISE EXCEPTION 'document not pending';\n  END IF;\n\n  IF v_doc.created_by IS DISTINCT FROM v_uid\n     AND NOT public.is_admin()\n     AND NOT public.is_dev() THEN\n    RAISE EXCEPTION 'only creator can recall';\n  END IF;\n\n  FOR v_step IN\n    SELECT * FROM public.workflow_steps\n    WHERE document_id = p_doc\n    ORDER BY step_number\n    FOR UPDATE\n  LOOP\n    IF v_step.step_number > 1\n       AND v_step.status IN ('active', 'done')\n       AND v_step.assigned_to IS NOT NULL\n       AND v_step.assigned_to <> v_doc.created_by THEN\n      v_notify := array_append(v_notify, v_step.assigned_to);\n    END IF;\n\n    IF v_step.step_number = 1 THEN\n      UPDATE public.workflow_steps SET\n        status = 'active',\n        action_taken = NULL,\n        note = NULL,\n        revision_section = NULL,\n        action_at = NULL,\n        completed_at = NULL,\n        rejected_by = NULL,\n        deadline_datetime = public.step_deadline_ts(v_step.deadline_days)\n      WHERE id = v_step.id;\n    ELSE\n      UPDATE public.workflow_steps SET\n        status = 'pending',\n        action_taken = NULL,\n        note = NULL,\n        revision_section = NULL,\n        action_at = NULL,\n        completed_at = NULL,\n        rejected_by = NULL,\n        deadline_datetime = NULL\n      WHERE id = v_step.id;\n    END IF;\n  END LOOP;\n\n  UPDATE public.documents SET\n    status = 'draft',\n    current_step = 1,\n    updated_at = now()\n  WHERE id = p_doc;\n\n  INSERT INTO public.document_history (document_id, action, performed_by, note)\n  VALUES (\n    p_doc,\n    'ดึงเอกสารกลับ',\n    v_uid,\n    'ผู้จัดทำดึงเอกสารกลับเป็นฉบับร่าง — รีเซ็ตขั้นตอนอนุมัติทั้งหมด'\n  );\n\n  RETURN jsonb_build_object(\n    'notify_ids', to_jsonb(v_notify)\n  );\nEND;\n$$;\n\nGRANT EXECUTE ON FUNCTION public.recall_document(uuid) TO authenticated;\n\n-- ── 3. schema version marker ────────────────────────────────────────────────\nINSERT INTO public.app_settings (key, value, label, value_type)\nVALUES ('schema_version', '3', 'เวอร์ชัน schema ที่ frontend ต้องการ', 'text')\nON CONFLICT (key) DO UPDATE\n  SET value = EXCLUDED.value, updated_at = now();\n","24_private_storage_bucket.sql":"-- ============================================================================\n-- SAEDU Flow — Private documents bucket + Storage RLS\n-- ============================================================================\n-- รันหลัง migration_auth_rls + enable_rls (และหลัง frontend ที่ใช้ signed URL deploy แล้ว)\n-- ทำให้ bucket `documents` ไม่ public — client ใช้ createSignedUrl() แทน public URL\n-- idempotent — รันซ้ำได้\n--\n-- ⚠️  Deploy พร้อมกับ frontend ที่มี resolveFilePath() / data-path แล้วเท่านั้น\n--     ถ้ารัน SQL ก่อน deploy frontend ไฟล์จะเปิดไม่ได้ชั่วคราว\n\n-- ── 1. ปิด public access บน bucket ─────────────────────────────────────────\nUPDATE storage.buckets\nSET public = false\nWHERE id = 'documents';\n\n-- สร้าง bucket ถ้ายังไม่มี (บางโปรเจกต์สร้างผ่าน Dashboard แล้ว)\nINSERT INTO storage.buckets (id, name, public)\nVALUES ('documents', 'documents', false)\nON CONFLICT (id) DO UPDATE SET public = false;\n\n-- ── 2. Storage RLS policies (authenticated เท่านั้น) ─────────────────────\n-- สอดคล้องกับแนวคิด document_files: สมาชิกที่ล็อกอินแล้วอ่านไฟล์ร่วมกันได้\n\nDROP POLICY IF EXISTS documents_public_read ON storage.objects;\nDROP POLICY IF EXISTS documents_auth_select ON storage.objects;\nDROP POLICY IF EXISTS documents_auth_insert ON storage.objects;\nDROP POLICY IF EXISTS documents_auth_update ON storage.objects;\nDROP POLICY IF EXISTS documents_auth_delete ON storage.objects;\n\nCREATE POLICY documents_auth_select ON storage.objects\n  FOR SELECT TO authenticated\n  USING (bucket_id = 'documents');\n\nCREATE POLICY documents_auth_insert ON storage.objects\n  FOR INSERT TO authenticated\n  WITH CHECK (bucket_id = 'documents');\n\nCREATE POLICY documents_auth_update ON storage.objects\n  FOR UPDATE TO authenticated\n  USING (bucket_id = 'documents')\n  WITH CHECK (bucket_id = 'documents');\n\nCREATE POLICY documents_auth_delete ON storage.objects\n  FOR DELETE TO authenticated\n  USING (bucket_id = 'documents');\n\n-- ── 3. หมายเหตุ Edge Function convert-docx ─────────────────────────────────\n-- validateStorageUrl รองรับ signed URL แล้ว — deploy send-email/convert-docx ชุดล่าสุดด้วย\n","26_phase1_dev_extras.sql":"-- ============================================================================\n-- 26_phase1_dev_extras.sql — สิทธิ์เพิ่มสำหรับ ROLE-DEV (ระยะ 1)\n-- รันใน Supabase SQL Editor ถ้าเคยรัน 17_create_dev_role.sql ไปแล้วก่อนมี policy นี้\n-- idempotent — รันซ้ำได้ปลอดภัย\n-- ============================================================================\n\ndrop policy if exists form_templates_write_dev on public.form_templates;\ncreate policy form_templates_write_dev on public.form_templates\n  for all using (public.is_dev()) with check (public.is_dev());\n","27_phase2_dev_ops.sql":"-- ============================================================================\n-- 27_phase2_dev_ops.sql — เครื่องมือซ่อมเอกสารขั้นสูงสำหรับ ROLE-DEV (ระยะ 2)\n-- รันใน Supabase SQL Editor — idempotent\n-- ============================================================================\n\ndrop policy if exists documents_delete_dev on public.documents;\ncreate policy documents_delete_dev on public.documents\n  for delete using (public.is_dev());\n\ndrop policy if exists document_files_delete_dev on public.document_files;\ncreate policy document_files_delete_dev on public.document_files\n  for delete using (public.is_dev());\n\ndrop policy if exists workflow_steps_delete_dev on public.workflow_steps;\ncreate policy workflow_steps_delete_dev on public.workflow_steps\n  for delete using (public.is_dev());\n","28_phase3_dev_users.sql":"-- ============================================================================\n-- 28_phase3_dev_users.sql — จัดการผู้ใช้แบบจำกัดสำหรับ ROLE-DEV (ระยะ 3)\n-- รันใน Supabase SQL Editor — idempotent\n--\n-- สิ่งที่ได้:\n--   ✓ อ่านรายชื่อ users ทั้งหมด (ยกเว้นแก้แถว ROLE-SYS ไม่ได้)\n--   ✓ อนุมัติ/ปฏิเสธ/เปิด-ปิดบัญชี/แก้ role (ห้ามตั้งเป็น ROLE-SYS)\n--   ✗ ลบผู้ใช้ / สร้างผู้ใช้ — ยังต้องใช้แอดมิน + Edge Functions เดิม\n-- ============================================================================\n\ndrop policy if exists users_select_dev on public.users;\ncreate policy users_select_dev on public.users\n  for select using (public.is_dev());\n\ndrop policy if exists users_update_dev on public.users;\ncreate policy users_update_dev on public.users\n  for update\n  using (public.is_dev() and role_code <> 'ROLE-SYS')\n  with check (public.is_dev() and role_code <> 'ROLE-SYS');\n","29_cron_overdue.sql":"-- ============================================================================\n-- SAEDU Flow — cron ตรวจเอกสารเลยกำหนด (รายวัน 01:00 น. ไทย)\n-- ============================================================================\n-- ต้อง deploy Edge Function ก่อน:\n--   npx supabase secrets set OVERDUE_CRON_SECRET=<รหัสสุ่มยาว ๆ>\n--   npx supabase functions deploy check-overdue --no-verify-jwt\n--\n-- ตั้งค่า secret เดียวกันใน app_settings (pg_cron อ่านจากตารางนี้):\n--   UPDATE app_settings SET value = '<รหัสเดียวกับ OVERDUE_CRON_SECRET>'\n--   WHERE key = 'overdue_cron_secret';\n--\n-- ทางเลือก: ตั้ง Schedule ใน Supabase Dashboard → Edge Functions → check-overdue\n--   cron: 0 18 * * * (UTC) = 01:00 Asia/Bangkok\n--   Header: x-cron-secret = <ค่า OVERDUE_CRON_SECRET>\n-- ============================================================================\n\n-- คีย์สำหรับ cron (แอดมินใส่ค่า secret จริงหลังรัน)\nINSERT INTO public.app_settings (key, value, label, value_type)\nVALUES (\n  'overdue_cron_secret', '',\n  'รหัสลับเรียก check-overdue (ต้องตรงกับ OVERDUE_CRON_SECRET ใน Edge Functions)',\n  'text'\n)\nON CONFLICT (key) DO NOTHING;\n\nINSERT INTO public.app_settings (key, value, label, value_type)\nVALUES ('overdue_cron_enabled', 'true', 'เปิด cron ตรวจเลยกำหนด', 'boolean')\nON CONFLICT (key) DO NOTHING;\n\n-- pg_cron + pg_net (Supabase มีให้ — ถ้า extension ไม่มี ให้ใช้ Dashboard Schedule แทน)\nCREATE EXTENSION IF NOT EXISTS pg_cron WITH SCHEMA pg_catalog;\nCREATE EXTENSION IF NOT EXISTS pg_net WITH SCHEMA extensions;\n\n-- ลบ job เดิม (ถ้ามี) แล้วสร้างใหม่\nDO $$\nDECLARE\n  jid int;\nBEGIN\n  SELECT jobid INTO jid FROM cron.job WHERE jobname = 'saedu-check-overdue' LIMIT 1;\n  IF jid IS NOT NULL THEN\n    PERFORM cron.unschedule(jid);\n  END IF;\nEND $$;\n\nSELECT cron.schedule(\n  'saedu-check-overdue',\n  '0 18 * * *',\n  $$\n  SELECT net.http_post(\n    url := 'https://jrubupvzltxqstzcpoov.supabase.co/functions/v1/check-overdue',\n    headers := jsonb_build_object(\n      'Content-Type', 'application/json',\n      'x-cron-secret', coalesce(\n        (SELECT value FROM public.app_settings WHERE key = 'overdue_cron_secret'),\n        ''\n      )\n    ),\n    body := '{}'::jsonb\n  ) AS request_id;\n  $$\n);\n\n-- อัปเดต schema version\nINSERT INTO public.app_settings (key, value, label, value_type)\nVALUES ('schema_version', '3', 'เวอร์ชัน schema ที่ frontend ต้องการ', 'text')\nON CONFLICT (key) DO UPDATE\n  SET value = EXCLUDED.value, updated_at = now();\n"};
